/** PenyuGuard English / Bahasa Melayu. Offline, dependency-free locale layer.
 * Translates the UI only, never mutates case records or user-written evidence.
 */
const KEY='penyuguard:language';
let locale='en';
try { locale=localStorage.getItem(KEY)==='ms'?'ms':'en'; } catch {}
export const getLocale=()=>locale;
export function setLocale(next){locale=next==='ms'?'ms':'en';try{localStorage.setItem(KEY,locale);}catch{}document.documentElement?.setAttribute?.('lang',locale);window.dispatchEvent(new CustomEvent('pg:locale'));}
