export function translateText(value){
 if(locale!=='ms'||typeof value!=='string')return value;
 const key=value.trim().replace(/\u00a0/g,' ');
 if(!key)return value;
 let result=ms[key];
 if(result===undefined){for(const [rx,fn] of templateRules){const m=key.match(rx);if(m){result=fn(...m);break;}}}
 if(result===undefined && key.includes(' · ')){const parts=key.split(' · ');const translated=parts.map(part=>translateText(part));if(translated.some((v,i)=>v!==parts[i]))result=translated.join(' · ');}
 if(result===undefined)return value;
 const left=value.match(/^\s*/)?.[0]||'',right=value.match(/\s*$/)?.[0]||'';
 return left+result+right;
}
export function translateSubtree(root){
 if(locale!=='ms'||!root)return;
 const doc=root.ownerDocument||document;
 const walker=doc.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(node){return node.parentElement?.closest('script,style,textarea,[contenteditable="true"],.user-authored')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT;}});
 const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){const next=translateText(node.nodeValue);if(next!==node.nodeValue)node.nodeValue=next;}
 const elements=root.querySelectorAll?.('[placeholder],[aria-label],[title],[alt],[value]')||[];
 for(const el of elements){for(const attr of ['placeholder','aria-label','title','alt']){const old=el.getAttribute(attr);if(old){const replacement=translateText(old);if(replacement!==old)el.setAttribute(attr,replacement);}}}
}
export function translateMessage(msg){return translateText(msg);}
